const fs=require("fs");
const read=(f)=>{ if(!fs.existsSync(f)) throw new Error(f+" missing"); const raw=fs.readFileSync(f,"utf8").trim(); const n=Number(raw); if(!Number.isFinite(n)) throw new Error(f+" not numeric: "+JSON.stringify(raw)); return n; };
const seed=read("seed.txt"), s1=read("stage1.txt"), s2=read("stage2.txt"), s3=read("stage3.txt");
