const obj={stage1:s1,stage2:s2,stage3:s3};
fs.writeFileSync("answer.json",JSON.stringify(obj,null,2)+"\n");
console.log("answer.json written from saved files:",JSON.stringify(obj));
' && echo '--- answer.json ---' && cat answer.json && echo '--- re-verify answer.json ---' && node -e '
