for(const k of ["stage1","stage2","stage3"]) if(typeof a[k]!=="number") throw new Error(k+" not a number: "+typeof a[k]);
const f1=Number(fs.readFileSync("stage1.txt","utf8").trim()), f2=Number(fs.readFileSync("stage2.txt","utf8").trim()), f3=Number(fs.readFileSync("stage3.txt","utf8").trim());
