arguments.command:
node -e '
const fs=require("fs");
const read=(f)=>{ if(!fs.existsSync(f)) throw new Error("MISSING "+f); const raw=fs.readFileSync(f,"utf8").trim(); const n=Number(raw); if(raw===""||!Number.isFinite(n)) throw new Error(f+" not numeric: "+JSON.stringify(raw)); return n; };
const seed=read("seed.txt"), s1=read("stage1.txt"), s2=read("stage2.txt"), s3=read("stage3.txt");
const a=JSON.parse(fs.readFileSync("answer.json","utf8"));
const checks=[
 ["stage1 = seed + 2", s1===seed+2],
 ["stage2 = stage1^2", s2===s1*s1],
 ["stage3 = stage2 - 4", s3===s2-4],
 ["answer keys exact", Object.keys(a).sort().join(",")==="stage1,stage2,stage3"],
 ["answer types number", ["stage1","stage2","stage3"].every(k=>typeof a[k]==="number")],
 ["answer matches files", a.stage1===s1 && a.stage2===s2 && a.stage3===s3]
];
let ok=true;
for(const [n,p] of checks){ console.log((p?"PASS":"FAIL")+": "+n); if(!p) ok=false; }
console.log("values", JSON.stringify({seed,s1,s2,s3,answer:a}));
process.exit(ok?0:1);
'; echo "exit=$?"
